SELECT l.id, l.email, l.band, l.value_usd, l.first_touch, l.attribution_path, l.created_at
FROM leads l
WHERE l.created_at > NOW() - INTERVAL '180 days' AND l.merged_into IS NULL;

parameters.jsCode:
// Match leads to content by slug appearing anywhere in the attribution path or
// utm_content. Unmatched leads are reported as unattributed rather than
// distributed across content - inventing attribution is worse than admitting none.
const rows = $input.all().map((i) => i.json);
const content = rows.filter((r) => r.slug !== undefined);
const leads = rows.filter((r) => r.email !== undefined);

const byContent = content.map((c) => {
  const matched = leads.filter((l) => String(l.attribution_path || '').toLowerCase().includes(String(c.slug).toLowerCase())
    || String(l.first_touch || '').toLowerCase().includes(String(c.slug).toLowerCase()));
  return {
    slug: c.slug, title: c.title, platform: c.platform, url: c.url,
    published_at: c.published_at,
    leads: matched.length,
    hot_leads: matched.filter((l) => l.band === 'hot').length,
    pipeline_usd: matched.reduce((s, l) => s + Number(l.value_usd || 0), 0)
  };
}).sort((a, b) => b.pipeline_usd - a.pipeline_usd || b.leads - a.leads);

const attributed = byContent.reduce((s, c) => s + c.leads, 0);
return byContent.map((c) => ({ json: Object.assign({}, c, {
  total_leads: leads.length,
  unattributed_leads: leads.length - attributed
}) }));
